INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6621160, 988887, 117534, '<td valign="top">hummm a Texas thing??</td>', 'hummm a Texas thing??', '2011-12-19 00:07:37.000000', NULL, 1),
(6621164, 989026, 117534, '<td valign="top">Very nice love the angle you took</td>', 'Very nice love the angle you took', '2011-12-19 00:09:05.000000', NULL, 1),
(6621178, 988846, 10785, '<td valign="top">The slight tilt adds a bit of interest. The darker background doesn''t do too much to add to the focal point of the subject. (To me it looks like the background was made artifically darker.)</td>', 'The slight tilt adds a bit of interest. The darker background doesn''t do too much to add to the focal point of the subject. (To me it looks like the background was made artifically darker.)', '2011-12-19 00:13:27.000000', NULL, 1),
(6621187, 988887, 10785, '<td valign="top">It looks like your slow shutter speed captured some movement in the trees making the background look as though it is an oil painting. That contrasts with the foreground which is nicely lit and in focus with no movement. I like that you kept the entire tree in the picture, but it does take the spotlight away from the subject metal.</td>', 'It looks like your slow shutter speed captured some movement in the trees making the background look as though it is an oil painting. That contrasts with the foreground which is nicely lit and in focus with no movement. I like that you kept the entire tree in the picture, but it does take the spotlight away from the subject metal.', '2011-12-19 00:16:49.000000', NULL, 1),
(6621196, 988523, 10785, '<td valign="top">This is a story telling image!</td>', 'This is a story telling image!', '2011-12-19 00:20:06.000000', NULL, 1),
(6621202, 989052, 32011, '<td valign="top">Okay... THIS is an amazing image.  The desat on the eye is perfect... it''s a very powerful, sexy image... this will do well!</td>', 'Okay... THIS is an amazing image.  The desat on the eye is perfect... it''s a very powerful, sexy image... this will do well!', '2011-12-19 00:22:41.000000', NULL, 1),
(6621210, 988806, 32011, '<td valign="top">Oh!  This is the image I was going to take for this challenge.  Though, I reckon you''ve done better than I would have... making me happy that time and events conspired against me this week to ensure I didn''t submit anything.<br/> <br/>Well done.  Great composition and processing.  One criticism, if I was to nitpick... might have paid to lose the lines in the lower left... but otherwise perfect in my book... giving it a 9.</td>', 'Oh!  This is the image I was going to take for this challenge.  Though, I reckon you''ve done better than I would have... making me happy that time and events conspired against me this week to ensure I didn''t submit anything. Well done.  Great composition and processing.  One criticism, if I was to nitpick... might have paid to lose the lines in the lower left... but otherwise perfect in my book... giving it a 9.', '2011-12-19 00:26:49.000000', NULL, 1),
(6621211, 988776, 32011, '<td valign="top">Wow!  Wonderful geometry.  Fantastic processing... your vision in capturing and processing this is spectacular.  This HAS TO do well in this challenge.  A 9 from me (for now... i.e I wouldn''t be surprised if I''m back to look at it some more and bump it up a notch).</td>', 'Wow!  Wonderful geometry.  Fantastic processing... your vision in capturing and processing this is spectacular.  This HAS TO do well in this challenge.  A 9 from me (for now... i.e I wouldn''t be surprised if I''m back to look at it some more and bump it up a notch).', '2011-12-19 00:26:51.000000', NULL, 1),
(6621212, 989033, 32011, '<td valign="top">I love these night time refinery/factory images.  Works very well in B&amp;W.  I like the balance and clarity of this image... border might hurt you with the letterbox haters, which I''m not one of... just saying.  Anyway, I like your work.</td>', 'I love these night time refinery/factory images.  Works very well in B&W.  I like the balance and clarity of this image... border might hurt you with the letterbox haters, which I''m not one of... just saying.  Anyway, I like your work.', '2011-12-19 00:26:53.000000', NULL, 1),
(6621219, 989053, 10785, '<td valign="top">Standard shot of the statue without any added interest such as colors in the sky, sunrise/sunset, etc. Nice use of the telephoto to show of the detail but the detail was lost in the lack of sharpness.</td>', 'Standard shot of the statue without any added interest such as colors in the sky, sunrise/sunset, etc. Nice use of the telephoto to show of the detail but the detail was lost in the lack of sharpness.', '2011-12-19 00:30:44.000000', NULL, 1),
