(6625519, 988872, 96751, '<td valign="top">Did a bit better than you thought!</td>', 'Did a bit better than you thought!', '2011-12-26 00:25:52.000000', NULL, 0),
(6625520, 988892, 96751, '<td valign="top">Such lovely detail in the metal work.</td>', 'Such lovely detail in the metal work.', '2011-12-26 00:26:26.000000', NULL, 0),
